mapper.select:
SELECT N.NOTICENUM, N.TITLE, N.CONTENT, N.REGDATE, M.STUDENTID
FROM NOTICE N JOIN MEMBER M ON N.STUDENTID = M.STUDENTID
WHERE NOTICENUM = #{noticeNum}

SELECT FILENUM, REGEXP_REPLACE(TITLE, '^.*/[sb]_[^_]+_', '') AS TITLE,, REGDATE, TITLE AS FILES, NOTICENUM
FROM NOTICEFILE
WHERE NOTICENUM = #{noticeNum}
